def link(url,label,cls='button'):return f'<a class="{cls}" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def card(k,title,desc,img):
 artwork=f'<img src="/assets/{img}.webp" alt="" loading="lazy">' if img else ''
 number='01' if k=='cyberfoundations' else '02'
 return f'<a class="program-card {k} {"program-summary" if not img else ""}" href="/{k}/">{artwork}<div><span class="path-number" aria-hidden="true">{number}</span><span class="eyebrow">{"Tier I · Explore the foundations" if k=="cyberfoundations" else "Tier II · Specialize in digital trust"}</span><h2>{title}</h2><p>{desc}</p><span class="text-link">Explore the pathway <b>↗</b></span></div></a>'

def intro(tag,title,desc):return f'<section class="intro wrap"><span class="eyebrow">{tag}</span><h1>{title}</h1><p class="lead">{desc}</p></section>'
def item(n,title,desc):return f'<article class="line-item"><span>{n}</span><div><h3>{title}</h3><p>{desc}</p></div></article>'
def resource(title,desc,repo):return f'<article class="resource"><span class="eyebrow">Public GitHub resource</span><h3>{title}</h3><p>{desc}</p>{link(gh+repo,"View repository","text-link")}</article>'
